export const DEFAULT_PERSONA = PERSONAS[0]!;

export function personaById(id: string | null | undefined): Persona {
  return PERSONAS.find((p) => p.id === id) ?? DEFAULT_PERSONA;
}

/** "a" or "an", by the sound the word starts with, for the handful of words here. */
export function article(noun: string): "a" | "an" {
  const first = noun.charAt(0).toLowerCase();
  // "RLCS" is read letter by letter and starts with an "ar"; the rest by their vowel.
  if (/^[A-Z]{2,}/.test(noun)) return /^[aefhilmnorsx]/.test(first) ? "an" : "a";
  return /^[aeiou]/.test(first) ? "an" : "a";
}

/** The rest of the personas' scenes, in the page's order, for the lede's list. */
export function otherScenes(persona: Persona, count: number): string[] {
  return PERSONAS.filter((p) => p.id !== persona.id)
    .slice(0, count)
    .map((p) => p.scene.charAt(0).toLowerCase() + p.scene.slice(1));
}

/** Two other vocabularies, so the reasons still show the range. */
export function otherVocabularies(persona: Persona, count: number): string[] {
  return PERSONAS.filter((p) => p.id !== persona.id)
    .slice(0, count)
    .map((p) => p.vocabulary);
}

const KEY = "runlog:persona";

export function savedPersona(storage: Pick<Storage, "getItem"> | null): Persona {
  try {
    return personaById(storage?.getItem(KEY));
  } catch {
    return DEFAULT_PERSONA;
  }
}

export function savePersona(storage: Pick<Storage, "setItem"> | null, persona: Persona): void {
  try {
    storage?.setItem(KEY, persona.id);
  } catch {
    // Storage is a convenience; the page works without remembering.
  }
}

import { describe, expect, it } from "vitest";
import { DEFAULT_PERSONA, PERSONAS, article, otherScenes, otherVocabularies, personaById, savePersona, savedPersona } from "./personas.ts";

/**
 * Every persona is a full example: what the page shows changes as a set,
 * so a persona missing a piece would leave the page half about someone
 * else. And the words that get read aloud in the heading have to scan.
 */
describe("the personas", () => {
  it("are each a complete example drawn from one shipped pack", () => {
    const ids = new Set<string>();
    for (const p of PERSONAS) {
      expect(ids.has(p.id), p.id).toBe(false);
      ids.add(p.id);
      expect(p.packId).toMatch(/^com\.scrthq\.runlog\./);
      expect(p.log).toHaveLength(4);
      expect(p.log.filter((l) => l.heat)).toHaveLength(1);
      expect(p.state.length).toBeGreaterThanOrEqual(2);
      expect(p.closing).toMatch(/\.$/);
      expect(p.scene).toMatch(/^[A-Z]/);
      expect(p.vocabulary).toMatch(/^an? [A-Z]\w+ of [A-Z]\w+$/);
      expect(p.clock).toContain(p.at);
    }
  });

  it("read as a sentence: a streamer, an Elden Lord, an RLCS champion", () => {
    expect(article("streamer")).toBe("a");
    expect(article("Elden Lord")).toBe("an");
    expect(article("RLCS champion")).toBe("an");
    expect(article("human")).toBe("a");
  });

  it("fall back to the first for an unknown or missing choice", () => {
    expect(personaById("nobody")).toBe(DEFAULT_PERSONA);
    expect(personaById(undefined)).toBe(DEFAULT_PERSONA);
    expect(personaById("elden-lord").packTitle).toBe("Elden Ring: TarnishedTool");
  });

  it("list the others without repeating the one chosen", () => {
    const lord = personaById("elden-lord");
    expect(otherScenes(lord, 3)).toHaveLength(3);
    expect(otherScenes(lord, 3)).not.toContain("ten minutes with the world against you");
    expect(otherVocabularies(lord, 2)).not.toContain(lord.vocabulary);
  });

  it("are remembered on the device, and forgotten gracefully", () => {
    const store = new Map<string, string>();
    const storage = { getItem: (k: string) => store.get(k) ?? null, setItem: (k: string, v: string) => void store.set(k, v) };
    savePersona(storage, personaById("learner"));
    expect(savedPersona(storage).id).toBe("learner");
    expect(savedPersona(null)).toBe(DEFAULT_PERSONA);
    const broken = {
      getItem: () => {
        throw new Error("no");
      },
    };
    expect(savedPersona(broken)).toBe(DEFAULT_PERSONA);
  });
});

